(* [comment removed for export] *)
Definition pm_trace (sp0z : Z) : list Z := if pm_short sp0z then [0x5cbf4] else [0x5cbf4; 0x5df44].
Definition pm_trace_hash (sp0z : Z) : Z := if pm_short sp0z then 0x10e2475ff98bf48e else 0x427c35ee793336da.
Definition pm_nframes (sp0z : Z) : Z := if pm_short sp0z then 2 else 3.          (* [comment removed for export] *)
Definition pm_tab_slot (sp0z : Z) : Z := if pm_short sp0z then 5277072 else 2985664.   (* [comment removed for export] *)
(* [comment removed for export] *)
Definition depot0 (sp0z : Z) (X : pm_syms) : depot :=
  mkDepot 1 (pm_nframes sp0z) (fun _ => pm_trace_hash sp0z)
          (fun b => if b =? bucket (pm_trace_hash sp0z) then [1] else []) (ps_b21 X) (ps_b22 X).

