  Lemma kp_b21f : 6811648 <= ps_b21 X /\ ps_b21 X + 0x100000 <= page_down sp0z - 8388608 /\ ps_b21 X mod 4096 = 0.
  Proof. pose proof (kp_facts _ _ kp_b21) as (A & B & C & D & _). cbn [fst snd] in A, B, C, D. lia. Qed.
  Lemma kp_b22f : 6811648 <= ps_b22 X /\ ps_b22 X + 0x800000 <= page_down sp0z - 8388608 /\ ps_b22 X mod 4096 = 0.
  Proof. pose proof (kp_facts _ _ kp_b22) as (A & B & C & D & _). cbn [fst snd] in A, B, C, D. lia. Qed.
