  Lemma seg_rom_bss_tab : forall z, 2143064 <= z < 6337368 -> PropExec.seg_rom ASEGS (wa z) = Some (b8 0).
  Proof.
    intros z Hz. unfold PropExec.seg_rom, memory_read. rewrite wa_unsigned by lia. change (Z.of_N 1) with 1.
    replace (find_segment ASEGS z 1) with (Some Asan_segment_003).
    2:{ rewrite asan_segs_eq. cbn -[Z.leb Z.add Z.of_N]. cbn [Z.of_N seg_base seg_size Asan_segment_000 Asan_segment_001 Asan_segment_002 Asan_segment_003].
        destruct (Z.leb_spec 65536 z); destruct (Z.leb_spec (z + 1) (65536 + 249856)); cbn [andb]; try lia;
        destruct (Z.leb_spec 315392 z); destruct (Z.leb_spec (z + 1) (315392 + 819200)); cbn [andb]; try lia;
        destruct (Z.leb_spec 1134592 z); destruct (Z.leb_spec (z + 1) (1134592 + 32768)); cbn [andb]; try lia;
        destruct (Z.leb_spec 1167360 z); destruct (Z.leb_spec (z + 1) (1167360 + 5644288)); cbn [andb]; try lia. reflexivity. }
    replace (seg_readable Asan_segment_003) with true by reflexivity.
    cbn [seg_bytes seg_base N.to_nat Pos.to_nat Pos.iter_op segment_read_bytes Asan_segment_003].
    change (Z.of_N 1409024%N) with 1167360.
    cbn [Asan_segment_003 seg_bytes]. change (N.to_nat 1) with 1%nat. cbn [segment_read_bytes].
    match goal with |- context [segment_byte_at ?l ?o] => replace (segment_byte_at l o) with (Some (b8 0)); [reflexivity|] end.
    symmetry. eapply (AsanHexTree.segment_byte_at_zero_pt _ _ _ _ AsMainIfaceDepotScan.tab_zero_scan); [rewrite asan_len3; cbn; lia | lia].
